package com.sphere.core.clhep.geometry;

import com.sphere.core.clhep.CMath;

/**
 * CLHEP's HepGeom::Point3D&lt;float&gt; (Geometry/Point3D.h, Point3D.cc): a point, which a transformation moves
 * by its rotation and its translation. Generated by gen_geometry.py.
 */
public class Point3DF extends BasicVector3DF {

    public Point3DF() {
        super();
    }

    public Point3DF(float x1, float y1, float z1) {
        super(x1, y1, z1);
    }

    /** From the first three of an array. */
    public Point3DF(float[] a) {
        super(a[0], a[1], a[2]);
    }

    public Point3DF(BasicVector3DF v) {
        super(v);
    }

    public float distance2() {
        return mag2();
    }

    public float distance2(Point3DF p) {
        final float dx = p.x() - x();
        final float dy = p.y() - y();
        final float dz = p.z() - z();
        return dx * dx + dy * dy + dz * dz;
    }

    public float distance() {
        return CMath.sqrtf(distance2());
    }

    public float distance(Point3DF p) {
        return CMath.sqrtf(distance2(p));
    }

    /** This point moved by m. */
    public Point3DF transform(Transform3D m) {
        final double vx = x();
        final double vy = y();
        final double vz = z();
        set((float) (m.xx() * vx + m.xy() * vy + m.xz() * vz + m.dx()),
            (float) (m.yx() * vx + m.yy() * vy + m.yz() * vz + m.dy()),
            (float) (m.zx() * vx + m.zy() * vy + m.zz() * vz + m.dz()));
        return this;
    }
}
